/** `version+commit` of this build, from scripts/buildId.mjs (Vite's `define`). */
declare const __PS_BUILD__: string;
/** The source tag a portal's own copy of the build gives new players without `?src=` (scripts/buildId.mjs), '' on the site. */
declare const __PS_DEFAULT_SRC__: string;
/** The iOS web bundle's version for hot updates (scripts/buildId.mjs), '0.0.0' outside the iOS workflows. */
declare const __PS_BUNDLE__: string;
